fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();

    // If the length is 0 or 1, just split in a way that both parts sum to original length,
    // but can't both be shorter than original length if length == 1,
    // so we follow the rule: must return arrays whose lengths add to original length.
    if len <= 1 {
        // Just return a cloned copy and an empty Vec.
        return (a.clone(), Vec::new());
    }

    // For length > 1, split into two non-empty parts such that both are strictly shorter than original.
    // We can split roughly in half.
    let mid = len / 2;

    // Use slicing and to_vec to produce new Vecs.
    let first_part = a[..mid].to_vec();
    let second_part = a[mid..].to_vec();

    (first_part, second_part)
}